"""Bounded character-Trie-aware column and row reordering."""

import heapq
from typing import List, Tuple

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Construct and score a small set of globally coherent column orders."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional frame and the most recently returned orders."""
        self.df = df
        self._last_orders = None

    @staticmethod
    def _cell_string(value) -> str:
        """Serialize one value, replacing scalar missing values with an empty string."""
        missing = pd.isna(value)
        if isinstance(missing, (bool, np.bool_)) and bool(missing):
            return ""
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return the exact common-prefix length using binary-search slicing."""
        if left == right:
            return len(left)
        low, high = 0, min(len(left), len(right))
        while low < high:
            mid = (low + high + 1) // 2
            if left[:mid] == right[:mid]:
                low = mid
            else:
                high = mid - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Score a fixed collection by sorted adjacent serialized-string LCPs."""
        if len(strings) < 2:
            return 0
        ordered = sorted(strings)
        score = 0
        previous = ordered[0]
        for current in ordered[1:]:
            score += len(current) if current == previous else cls._lcp(previous, current)
            previous = current
        return score

    @staticmethod
    def _positions(columns):
        """Map stringified labels to their source positions."""
        result = {}
        for i, name in enumerate(columns):
            result.setdefault(str(name), []).append(i)
        return result

    @classmethod
    def _edges(cls, columns, dependencies, blocks):
        """Translate dependency and merge requirements into directed index edges."""
        positions = cls._positions(columns)
        edges, seen = [], set()

        def add(left, right):
            if left != right and (left, right) not in seen:
                seen.add((left, right))
                edges.append((left, right))

        for pair in dependencies or []:
            if len(pair) == 2:
                left = positions.get(str(pair[0]), [])
                right = positions.get(str(pair[1]), [])
                if len(left) == 1 and len(right) == 1:
                    add(left[0], right[0])

        for block in blocks:
            for left, right in zip(block, block[1:]):
                add(left, right)
        return edges

    @classmethod
    def _constrained_order(cls, m, preference, columns, dependencies, blocks):
        """Topologically repair a preference while preserving requested constraints."""
        outgoing = [[] for _ in range(m)]
        indegree = [0] * m
        for left, right in cls._edges(columns, dependencies, blocks):
            outgoing[left].append(right)
            indegree[right] += 1

        rank = {x: i for i, x in enumerate(preference)}
        heap = [(rank.get(i, m + i), i) for i in range(m) if indegree[i] == 0]
        heapq.heapify(heap)
        result = []

        while heap:
            _, node = heapq.heappop(heap)
            result.append(node)
            for nxt in outgoing[node]:
                indegree[nxt] -= 1
                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank.get(nxt, m + nxt), nxt))

        return result if len(result) == m else list(preference)

    @staticmethod
    def _merge_blocks(m, columns, requested):
        """Collapse valid merge pairs into deterministic source-order blocks."""
        parent = list(range(m))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        positions = {}
        for i, name in enumerate(columns):
            positions.setdefault(str(name), []).append(i)

        for pair in requested or []:
            if len(pair) != 2:
                continue
            left = positions.get(str(pair[0]), [])
            right = positions.get(str(pair[1]), [])
            if len(left) == 1 and len(right) == 1:
                a, b = find(left[0]), find(right[0])
                if a != b:
                    parent[b] = a

        groups = {}
        for i in range(m):
            groups.setdefault(find(i), []).append(i)
        return sorted((sorted(v) for v in groups.values()), key=lambda x: x[0])

    @staticmethod
    def _statistics(text):
        """Return pair repetition, single repetition, and total character mass per column."""
        n, m = text.shape
        result = []
        for j in range(m):
            counts = {}
            for value in text[:, j]:
                counts[value] = counts.get(value, 0) + 1
            pair_mass = sum(len(value) * count * (count - 1)
                            for value, count in counts.items())
            repeat_mass = sum(len(value) * max(0, count - 1)
                              for value, count in counts.items())
            total = sum(len(value) * count for value, count in counts.items())
            result.append((pair_mass, repeat_mass, total))
        return result

    @staticmethod
    def _affinity(text, left, right):
        """Measure length-weighted repeated successor values within equal-left groups."""
        groups = {}
        for row, value in enumerate(text[:, left]):
            groups.setdefault(value, []).append(row)

        score = 0
        for rows in groups.values():
            if len(rows) < 2:
                continue
            counts = {}
            for row in rows:
                value = text[row, right]
                counts[value] = counts.get(value, 0) + 1
            score += sum(len(value) * count * (count - 1)
                         for value, count in counts.items())
        return score

    @classmethod
    def _block_candidates(cls, text, stats, blocks):
        """Build up to three greedy directed-affinity orders over column blocks."""
        if len(blocks) <= 1:
            return [sum(blocks, [])]

        mass = [sum(stats[j][0] for j in block) for block in blocks]
        active = sorted(
            range(len(blocks)),
            key=lambda k: (-mass[k], blocks[k][0])
        )[:48]

        # One representative per block bounds the directed affinity computation.
        representative = [block[0] for block in blocks]
        affinity = {}
        for a in active:
            for b in active:
                if a != b:
                    affinity[a, b] = cls._affinity(
                        text, representative[a], representative[b]
                    )

        candidates = []
        for seed in active[:3]:
            remaining = set(active)
            remaining.remove(seed)
            chain = [seed]

            while remaining:
                previous = chain[-1]
                nxt = max(
                    remaining,
                    key=lambda k: (
                        affinity.get((previous, k), 0),
                        mass[k],
                        -blocks[k][0],
                    ),
                )
                chain.append(nxt)
                remaining.remove(nxt)

            selected = set(chain)
            tail = sorted(
                (k for k in range(len(blocks)) if k not in selected),
                key=lambda k: (-mass[k], blocks[k][0]),
            )
            candidates.append([col for k in chain + tail for col in blocks[k]])

        return candidates

    @staticmethod
    def _serialize(text, orders):
        """Serialize every source row under its row-specific column permutation."""
        return [
            "".join(text[row, col] for col in orders[row])
            for row in range(text.shape[0])
        ]

    @staticmethod
    def _materialize(df, source, orders, serialized):
        """Sort by serialized keys and copy original values under each row's order."""
        row_order = sorted(range(source.shape[0]), key=lambda r: (serialized[r], r))
        values = np.empty(source.shape, dtype=object)
        public_orders = []

        for out, row in enumerate(row_order):
            order = orders[row]
            values[out, :] = [source[row, col] for col in order]
            public_orders.append([df.columns[col] for col in order])

        result = pd.DataFrame(
            values,
            index=df.index.take(row_order),
            columns=list(df.columns),
        )
        return result, public_orders

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List]]:
        """Evaluate a frequency baseline and bounded directed block-affinity candidates."""
        if not isinstance(df, pd.DataFrame):
            raise TypeError("df must be a pandas DataFrame")

        n, m = df.shape
        if n == 0 or m == 0:
            result = df.copy()
            orders = [[] for _ in range(n)]
            self._last_orders = orders
            return result, orders

        source = df.to_numpy(dtype=object, copy=True)
        text = np.empty((n, m), dtype=object)
        for col in range(m):
            text[:, col] = [self._cell_string(value) for value in source[:, col]]

        stats = self._statistics(text)
        columns = list(df.columns)
        blocks = self._merge_blocks(m, columns, col_merge)

        baseline = [
            col for col, _ in sorted(
                enumerate(stats),
                key=lambda item: (
                    -item[1][0],
                    -item[1][1],
                    -item[1][2],
                    item[0],
                ),
            )
        ]

        preferences = [baseline]
        preferences.extend(self._block_candidates(text, stats, blocks))

        candidates = []
        for preference in preferences:
            repaired = self._constrained_order(
                m, preference, columns, one_way_dep, blocks
            )
            candidates.append([repaired[:] for _ in range(n)])

        best_score = -1
        best_orders = None
        best_serialized = None

        for orders in candidates:
            serialized = self._serialize(text, orders)
            score = self._trie_score(serialized)
            if score > best_score:
                best_score = score
                best_orders = orders
                best_serialized = serialized

        result, public_orders = self._materialize(
            df, source, best_orders, best_serialized
        )
        if result.shape != df.shape:
            raise RuntimeError("Reordering changed DataFrame shape")

        self._last_orders = public_orders
        return result, public_orders

