                if indegree[nxt] == 0:
                    heapq.heappush(heap, (rank[nxt], nxt))

        return result if len(result) == m else list(preference)

    @staticmethod
    def _stats(text):
        """Compute repeated character mass for every column in one pass."""
        n, m = text.shape
        answer = []
        for j in range(m):
            counts = {}
            for value in text[:, j]:
                counts[value] = counts.get(value, 0) + 1
            pairs = sum(len(v) * c * (c - 1) for v, c in counts.items())
            repeats = sum(len(v) * max(0, c - 1) for v, c in counts.items())
            total = sum(len(v) * c for v, c in counts.items())
            answer.append((pairs, repeats, total))
        return answer

    @staticmethod
    def _merge_blocks(m, columns, requested):
        """Build deterministic indivisible blocks from valid column-merge pairs."""
        parent = list(range(m))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        positions = {}
        for i, name in enumerate(columns):
            positions.setdefault(str(name), []).append(i)

